$ {border-radius:999px;background:#0b101b;box-shadow:inset 0 4px 12px rgba(0,0,0,.9)}
$ .gl{position:absolute;inset:0;filter:url(#uib-ferro-goo)}
$ .al,$ .ar{position:absolute;top:50%;width:14px;height:14px;border-radius:50%;transform:translateY(-50%)}
$ .al{left:20px;background:#94a3b8}$ .ar{right:20px;background:#06b6d4}
$ .mb{position:absolute;top:7px;left:7px;width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 32% 28%,#f8fafc,#64748b);transition:transform .65s cubic-bezier(.68,-.45,.26,1.4),background .45s}
$ .sat{position:absolute;top:22px;left:22px;width:12px;height:12px;border-radius:50%;background:#cbd5e1;transition:transform .72s cubic-bezier(.34,1.65,.64,1),background .4s}
$ .sp{position:absolute;top:13px;left:16px;width:12px;height:6px;border-radius:99px;background:rgba(255,255,255,.75);transform:rotate(-28deg);transition:transform .65s cubic-bezier(.68,-.45,.26,1.4)}
$on .mb{transform:translateX(68px);background:radial-gradient(circle at 32% 28%,#ecfeff,#06b6d4)}
$on .sat{transform:translateX(52px) translateY(-11px);background:#34d399}
$on .sp{transform:translateX(68px) rotate(-28deg)}

$ {border-radius:12px;background:linear-gradient(180deg,#0b1020,#151c33);box-shadow:inset 0 0 0 2px #26304d,inset 0 4px 10px rgba(0,0,0,.8);transition:box-shadow .4s}
$ .bars{position:absolute;left:12px;right:12px;top:10px;bottom:10px;display:flex;justify-content:space-between;align-items:flex-end}
$ .bars u{width:10px;height:30%;border-radius:3px;background:#2a3556;transition:background .3s,height .3s}
$ .core{position:absolute;left:8px;top:8px;width:40px;height:40px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#6a7599,#2a3150);box-shadow:0 3px 8px rgba(0,0,0,.6);transition:transform .6s cubic-bezier(.5,1.4,.5,1),background .4s,box-shadow .4s}
$ .core b{position:absolute;inset:13px;border-radius:50%;background:#444d6e;transition:all .4s}
$on{box-shadow:inset 0 0 0 2px #b06bff,inset 0 0 22px #b06bff66,0 0 18px #b06bff55}
$on .bars u{background:#c58bff;animation:KF_b .6s ease-in-out infinite alternate}
$on .bars u:nth-child(2){animation-delay:.1s}$on .bars u:nth-child(3){animation-delay:.2s}$on .bars u:nth-child(4){animation-delay:.3s}
$on .core{transform:translateX(70px);background:radial-gradient(circle at 35% 30%,#f1dcff,#9b4dff 70%);box-shadow:0 0 20px #b06bff,0 0 40px #b06bff88}
$on .core b{background:#fff;box-shadow:0 0 14px #fff;animation:KF_p .5s infinite alternate}
@keyframes KF_b{from{height:25%}to{height:95%}}
@keyframes KF_p{to{transform:scale(1.35)}}

$ {border-radius:999px;overflow:hidden;background:linear-gradient(180deg,#0a1230,#1f2d63);box-shadow:inset 0 3px 8px rgba(0,0,0,.5);transition:background .7s}
$ .hills{position:absolute;left:-10px;right:-10px;bottom:-14px;height:34px;background:radial-gradient(ellipse at 25% 100%,#1a3a2e 55%,transparent 56%),radial-gradient(ellipse at 70% 100%,#122a22 60%,transparent 61%);transition:filter .7s}
$ .cel{position:absolute;left:7px;top:7px;width:42px;height:42px;border-radius:50%;background:#e8ecf5;box-shadow:inset -7px -4px 0 #c3cad9,0 0 14px #fff6;transition:transform .8s cubic-bezier(.4,1.2,.5,1),background .6s,box-shadow .6s}
$ .cel b{position:absolute;width:8px;height:8px;border-radius:50%;background:#c3cad9;left:10px;top:9px;transition:opacity .4s}
$ .cel b+b{width:5px;height:5px;left:24px;top:24px}
$on{background:linear-gradient(180deg,#4aa8ff,#bfe6ff)}
$on .hills{filter:brightness(1.8) saturate(1.4)}
$on .cel{transform:translateX(70px) rotate(180deg);background:radial-gradient(circle,#fffbe0,#ffd23f);box-shadow:0 0 0 6px #ffd23f55,0 0 0 12px #ffd23f22,0 0 24px #ffd23f}
$on .cel b{opacity:0}

$ {border-radius:8px;background:linear-gradient(180deg,#3a3f48,#23262c);box-shadow:inset 0 0 0 2px #14161a,0 3px 6px rgba(0,0,0,.4)}
$ .well{position:absolute;left:10px;right:36px;top:18px;height:22px;border-radius:11px;background:#0b0c0f;box-shadow:inset 0 3px 6px #000}
$ .lever{position:absolute;left:10px;top:10px;width:38px;height:38px;border-radius:8px;background:linear-gradient(180deg,#ffcf3a,#e09a00);box-shadow:0 4px 0 #8a5b00,0 6px 8px rgba(0,0,0,.5);transition:transform .45s cubic-bezier(.5,1.6,.5,1)}
$ .lamp{position:absolute;right:11px;top:19px;width:20px;height:20px;border-radius:50%;background:#4a1c1c;box-shadow:inset 0 2px 3px rgba(0,0,0,.6);transition:all .3s}
$ .guard{position:absolute;left:4px;right:30px;top:4px;bottom:4px;border:2px solid #ff4d3a;border-radius:6px;background:repeating-linear-gradient(45deg,#ff4d3a33 0 6px,transparent 6px 12px);transition:transform .35s,opacity .3s;transform-origin:top}
$h:hover .guard{transform:perspective(80px) rotateX(-40deg);opacity:.5}
$on .guard{transform:perspective(80px) rotateX(-80deg);opacity:0}
$on .lever{transform:translateX(52px)}
$on .lamp{background:#46ff6a;box-shadow:0 0 14px #46ff6a,0 0 28px #46ff6a99;animation:KF_l .8s infinite alternate}
@keyframes KF_l{to{filter:brightness(1.4)}}

$ {border-radius:999px;background:radial-gradient(circle at 20% 50%,#1b1233,#05030c);box-shadow:inset 0 0 0 2px #2a1d4d,inset 0 4px 10px #000;overflow:hidden}
