$ .disk{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 0deg,transparent,#ff8a3c,#ffd27a,#ff4d8d,transparent 70%);filter:blur(1px);-webkit-mask:radial-gradient(circle,transparent 12px,#000 13px);mask:radial-gradient(circle,transparent 12px,#000 13px);animation:KF_spin 2s linear infinite}
