$ .core{position:absolute;left:20px;top:20px;width:16px;height:16px;border-radius:50%;background:#000;box-shadow:0 0 0 2px #000,0 0 12px #000;transition:transform .8s cubic-bezier(.5,0,.2,1)}
$on .grp{transform:translateX(74px)}
$on .core{transform:translateX(74px) scale(1.2)}
$on .jet{opacity:1}
$on{box-shadow:inset 0 0 0 2px #7a4dff,inset 0 4px 10px #000,0 0 18px #7a4dff66}
@keyframes KF_spin{to{transform:rotate(360deg)}}

$ {border-radius:999px;background:linear-gradient(180deg,#0e1218,#1a2029);box-shadow:inset 0 4px 10px #000,inset 0 0 0 2px #2b323d}
$ .drop{position:absolute;left:6px;top:6px;width:44px;height:44px;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff 0 8%,#e9eef5 12%,#9aa6b6 50%,#4b5563 100%);box-shadow:0 4px 10px rgba(0,0,0,.6);transition:transform .8s cubic-bezier(.3,1.8,.4,1),width .4s,border-radius .4s}
