$on{box-shadow:inset 0 4px 10px #000,inset 0 0 0 2px #5ec8ff,0 0 14px #5ec8ff55}
@keyframes KF_s{0%{transform:translateX(0) scale(1)}35%{transform:translateX(50px) scale(1.4,.75)}70%{transform:translateX(76px) scale(.8,1.15)}100%{transform:translateX(70px) scale(1)}}

$ {border-radius:16px;border:2px solid #79747e;background:#e6e0e9;box-sizing:border-box;transition:background .25s,border-color .25s}
$ .k{position:absolute;top:50%;left:6px;width:16px;height:16px;margin-top:-8px;border-radius:50%;background:#79747e;transition:all .3s cubic-bezier(.2,0,0,1.2);display:flex;align-items:center;justify-content:center}
$ .k b{width:10px;height:5px;border-left:2.5px solid var(--ui-accent,#2b8cf0);border-bottom:2.5px solid var(--ui-accent,#2b8cf0);transform:rotate(-45deg) scale(0);margin-top:-2px;transition:transform .25s .05s}
$on{background:var(--ui-accent,#2b8cf0);border-color:var(--ui-accent,#2b8cf0)}
$on .k{left:24px;width:24px;height:24px;margin-top:-12px;background:#fff}
$on .k b{transform:rotate(-45deg) scale(1)}

$ {border-radius:15px;background:linear-gradient(135deg,rgba(125,211,252,.55),rgba(56,189,248,.3));border:1px solid rgba(255,255,255,.65);box-sizing:border-box;box-shadow:0 4px 14px rgba(14,116,144,.25),inset 0 1px 0 rgba(255,255,255,.7);transition:background .4s}
$ .k{position:absolute;left:3px;top:3px;width:22px;height:22px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#fff,rgba(255,255,255,.55) 55%,rgba(255,255,255,.3));box-shadow:0 3px 8px rgba(0,0,0,.2),inset 0 -2px 4px rgba(14,116,144,.25);transition:transform .45s cubic-bezier(.3,1.5,.5,1)}
$on{background:linear-gradient(135deg,rgba(52,211,153,.7),rgba(16,185,129,.4))}
$on .k{transform:translateX(26px)}

$ {border-radius:15px;background:linear-gradient(180deg,#e0f7ff,#a5ddf5);border:1px solid #fff;box-shadow:inset 0 2px 6px rgba(255,255,255,.9),inset 0 -3px 8px rgba(40,140,200,.35),0 2px 8px rgba(40,140,200,.25);box-sizing:border-box;transition:background .5s}
$ .k{position:absolute;left:3px;top:3px;width:22px;height:22px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#bfe9ff 60%,#7cc8ee);box-shadow:0 2px 6px rgba(20,100,160,.4);transition:transform .5s cubic-bezier(.3,1.4,.5,1)}
