$ {border-radius:15px;background:linear-gradient(180deg,#10131c,#1b2030);box-shadow:inset 0 2px 6px rgba(0,0,0,.8);transition:box-shadow .4s}
$ .k{position:absolute;left:3px;top:3px;width:24px;height:24px;transform:rotate(45deg) scale(.82);border-radius:4px;background:conic-gradient(from 45deg,#6b7280,#d1d5db,#4b5563,#9ca3af,#6b7280);box-shadow:0 0 0 2px rgba(255,255,255,.12);transition:transform .5s cubic-bezier(.3,1.4,.5,1),background .4s,box-shadow .4s}
