$ {border-radius:15px;background:linear-gradient(180deg,#9aa0a8,#d9dde2);box-shadow:inset 0 3px 6px rgba(0,0,0,.45),inset 0 -1px 0 rgba(255,255,255,.8),0 1px 0 rgba(255,255,255,.7)}
