$ {background:linear-gradient(180deg,#2a2d33,#1a1c20);border-radius:7px;box-shadow:inset 0 0 0 2px #0c0d10,0 2px 4px rgba(0,0,0,.4)}
$ .p{position:absolute;inset:5px 4px;border-radius:5px;background:linear-gradient(180deg,#5a5f69,#34383f);box-shadow:inset 0 1px 0 rgba(255,255,255,.25),0 4px 0 #101114;transform:perspective(90px) rotateX(16deg);transform-origin:50% 50%;transition:transform .22s cubic-bezier(.4,1.6,.5,1),background .25s}
$ .p b{position:absolute;left:50%;top:50%;width:10px;height:10px;margin:-5px 0 0 -5px;border-radius:50%;border:2px solid #b9bec7;box-sizing:border-box;transition:all .25s}
$on .p{transform:perspective(90px) rotateX(-16deg);background:linear-gradient(180deg,#ff7a59,#d9381e);box-shadow:inset 0 1px 0 rgba(255,255,255,.4),0 -3px 0 #101114,0 0 14px #ff5a36aa}
