$ .base{position:absolute;left:0;right:0;bottom:0;height:12px;border-radius:6px;background:linear-gradient(180deg,#6b7078,#3a3e45);box-shadow:inset 0 1px 0 rgba(255,255,255,.3)}
$ .arm{position:absolute;left:25px;bottom:6px;width:6px;height:26px;border-radius:3px;background:linear-gradient(90deg,#8d939b,#e6e9ee,#8d939b);transform-origin:50% 100%;transform:rotate(-38deg);transition:transform .35s cubic-bezier(.4,1.8,.5,1)}
$ .arm b{position:absolute;left:-3px;top:-6px;width:12px;height:12px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ff9d8a,#c92a12);box-shadow:0 2px 3px rgba(0,0,0,.4);transition:background .3s}
