$on .arm b{background:radial-gradient(circle at 35% 30%,#b9ffd0,#14a84a)}

$ {background:#9aa4b2;image-rendering:pixelated;box-shadow:0 0 0 4px #1b1b1f,inset 0 -4px 0 rgba(0,0,0,.25);clip-path:polygon(0 4px,4px 4px,4px 0,calc(100% - 4px) 0,calc(100% - 4px) 4px,100% 4px,100% calc(100% - 4px),calc(100% - 4px) calc(100% - 4px),calc(100% - 4px) 100%,4px 100%,4px calc(100% - 4px),0 calc(100% - 4px))}
$ .k{position:absolute;left:4px;top:4px;width:20px;height:20px;background:#fff;box-shadow:inset -4px -4px 0 #cfd4dc,0 0 0 4px #1b1b1f;transition:transform .35s steps(7,end)}
