$ {border-radius:15px;background:#d9dde6;box-shadow:inset 0 2px 4px rgba(0,0,0,.18);transition:background .3s}
$ .k{position:absolute;left:3px;top:3px;width:24px;height:24px;border-radius:50%;background:radial-gradient(circle at 32% 28%,#fff8,transparent 40%),#ff6b8b;box-shadow:0 3px 6px rgba(200,40,80,.4);transition:transform .5s cubic-bezier(.3,1.7,.5,1),background .3s;animation:KF_o .55s}
