$on .k{transform:translateX(26px);background:radial-gradient(circle at 32% 28%,#fff8,transparent 40%),#19c37d;box-shadow:0 3px 6px rgba(10,120,70,.4);animation:KF_i .6s}
@keyframes KF_i{0%{transform:translateX(0) scale(1)}35%{transform:translateX(20px) scale(1.35,.7)}65%{transform:translateX(28px) scale(.8,1.2)}100%{transform:translateX(26px) scale(1)}}
@keyframes KF_o{0%{transform:translateX(26px) scale(1)}35%{transform:translateX(6px) scale(1.35,.7)}65%{transform:translateX(-1px) scale(.8,1.2)}100%{transform:translateX(0) scale(1)}}

$ {border-radius:15px;overflow:hidden;background:linear-gradient(90deg,#0b1430,#162a5c);box-shadow:inset 0 0 0 2px #2c4a96}
$ .st{position:absolute;inset:0;background:radial-gradient(1.5px 1.5px at 20% 30%,#fff,transparent),radial-gradient(1.5px 1.5px at 48% 70%,#fff,transparent),radial-gradient(1.5px 1.5px at 70% 25%,#fff,transparent),radial-gradient(1px 1px at 88% 65%,#fff,transparent);opacity:.7}
$ .r{position:absolute;left:5px;top:10px;width:26px;height:10px;border-radius:10px 3px 3px 10px;background:linear-gradient(180deg,#fff,#c3cad8);transition:transform .7s cubic-bezier(.55,0,.2,1)}
