$ .r b{position:absolute;left:-12px;top:1px;width:12px;height:8px;border-radius:8px 0 0 8px;background:linear-gradient(270deg,#ffd34d,#ff6a1f,transparent);opacity:0;transform-origin:right;transition:opacity .3s}
