$on .r b{opacity:1;animation:KF_f .12s infinite alternate}
@keyframes KF_f{to{transform:scaleX(.6)}}

$ {border-radius:14px;background:#0a0a2a;box-shadow:inset 0 0 0 2px #2a4bff}
$ .d{position:absolute;left:30px;right:8px;top:12px;height:4px;background:radial-gradient(circle,#ffe14d 1.6px,transparent 2px) 0 0/9px 4px repeat-x;transition:left .5s linear}
$ .k{position:absolute;left:4px;top:4px;width:20px;height:20px;border-radius:50%;background:#ffe14d;transition:transform .5s linear}
$ .k b{position:absolute;inset:0;background:#0a0a2a;clip-path:polygon(50% 50%,100% 20%,100% 80%);animation:KF_c .3s infinite alternate}
