@keyframes KF_a{to{transform:rotate(360deg)}}
@keyframes KF_p{to{transform:scale(1.25)}}

$ {border-radius:15px;overflow:hidden;background:#cfeaf7;box-shadow:inset 0 0 0 2px #7fc4e8}
$ .w1,$ .w2{position:absolute;left:-30px;width:120px;height:120px;border-radius:42%;top:26px;transition:top .8s cubic-bezier(.4,0,.2,1);animation:KF_s 5s linear infinite}
$ .w1{background:rgba(31,150,214,.65)}
$ .w2{background:rgba(20,110,190,.55);animation-duration:7s;animation-direction:reverse}
$ .k{position:absolute;left:5px;top:5px;width:20px;height:20px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#ffe9a0 60%,#ffcc4d);box-shadow:0 0 8px #ffd96a;transition:transform .8s cubic-bezier(.4,1.2,.5,1)}
$on .w1,$on .w2{top:6px}
$on .k{transform:translateX(34px);background:radial-gradient(circle at 35% 30%,#fff,#e8f4ff 60%,#b8d8ee);box-shadow:0 0 6px #fff}
@keyframes KF_s{to{transform:rotate(360deg)}}

$ {border-radius:15px;background:linear-gradient(90deg,#9fe3ff 0,#4aa8e8 45%,#ff9a3c 55%,#ff3d1f 100%);background-size:200% 100%;background-position:0 0;box-shadow:inset 0 0 0 2px rgba(255,255,255,.45);transition:background-position .6s}
$ .k{position:absolute;left:4px;top:4px;width:22px;height:22px;background:radial-gradient(circle at 35% 30%,#fff,#bfe9ff 60%,#6bb7e6);clip-path:polygon(50% 0,100% 38%,82% 100%,18% 100%,0 38%);transition:transform .6s cubic-bezier(.4,1.3,.5,1),background .4s}
$on{background-position:100% 0}
$on .k{transform:translateX(30px);background:radial-gradient(circle at 50% 80%,#fff6c0,#ffb02e 50%,#ff3d1f);clip-path:polygon(50% 0,70% 30%,100% 55%,85% 100%,15% 100%,0 55%,30% 30%);animation:KF_f .3s infinite alternate}
@keyframes KF_f{to{transform:translateX(30px) scale(1.08,.94)}}

$ {border:2px solid var(--ui-toggle-off,#c4c9d1);border-radius:6px;box-sizing:border-box;transition:all .35s cubic-bezier(.4,0,.2,1)}
$ .k{position:absolute;left:2px;top:2px;width:16px;height:16px;border-radius:3px;background:var(--ui-toggle-off,#c4c9d1);transition:all .4s cubic-bezier(.4,1.5,.5,1);display:flex;align-items:center;justify-content:center}
$ .k b{width:8px;height:4px;border-left:2px solid #fff;border-bottom:2px solid #fff;transform:rotate(-45deg) scale(0);margin-top:-2px;transition:transform .3s .1s}
$on{border-color:var(--ui-accent,#2b8cf0);border-radius:12px}
$on .k{transform:translateX(20px);border-radius:50%;background:var(--ui-accent,#2b8cf0)}
$on .k b{transform:rotate(-45deg) scale(1)}

$ .sh{position:absolute;left:9px;top:2px;width:18px;height:20px;border:4px solid #aeb4bd;border-bottom:0;border-radius:10px 10px 0 0;box-sizing:border-box;transform-origin:100% 100%;transition:transform .45s cubic-bezier(.4,1.5,.5,1),border-color .3s}
$ .bd{position:absolute;left:3px;right:3px;bottom:2px;height:20px;border-radius:5px;background:linear-gradient(180deg,#ef6a55,#c5311b);box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 2px 3px rgba(0,0,0,.35);transition:background .35s}
$ .bd b{position:absolute;left:50%;top:5px;width:5px;height:5px;margin-left:-2.5px;border-radius:50%;background:#2a0d08}
$ .bd b:after{content:"";position:absolute;left:1.2px;top:4px;width:2.6px;height:6px;border-radius:2px;background:#2a0d08}
$on .sh{transform:translateY(-4px) rotateY(180deg) translateX(-9px);transform-origin:50% 100%}
$on .bd{background:linear-gradient(180deg,#4fd67a,#16a04a)}
